// sli.cpp - Artemis "Sound Loop Information" (.sli) parsing
//
// The format is a plain UTF-8 text member that sits next to an .ogg inside the
// archive and shares its name with ".sli" appended (moon.ogg / moon.ogg.sli).
// It is written by the engine's WaveLoopManager.cpp, which is why every shipped
// file carries the same three comment lines.
//
// Measured layout (388 labels across 228 shipped files, see audio.h):
//
//   #2.00\n
//   # Sound Loop Information (utf-8)\n
//   # Generated by WaveLoopManager.cpp\n
//   Label { Position=<n>;<spaces>Name='<utf8>';<spaces>}\n   x N
//
// The field padding is designed to line the columns up in an editor, so it is
// byte-counted, not character-counted: a katakana name is 3 bytes per glyph and
// still fits the same 18-byte block.  The parser below ignores the padding
// (any spacing works) while Save() reproduces the shipped byte layout exactly,
// which the self-test uses as a round-trip assertion on real game data.

#include "audio.h"

#include <cerrno>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace artemis {
namespace audio {

namespace {

const char* const kHeaderVersion = "#2.00";
const char* const kHeaderTitle = "# Sound Loop Information (utf-8)";
const char* const kHeaderWriter = "# Generated by WaveLoopManager.cpp";

// Column geometry of a Label line, in bytes.  17 for "Label { Position=",
// then an 18-byte "number;" block, an 18-byte "Name='..';" block, then padding
// that puts the closing brace on column 85 (line length 86).
constexpr int kLabelPrefix = 17;
constexpr int kPositionBlock = 18;
constexpr int kNameBlock = 18;
constexpr int kLabelLineLen = 86;

bool StartsWith(const std::string& s, size_t at, const char* lit) {
	size_t n = std::strlen(lit);
	return s.size() >= at + n && std::memcmp(s.data() + at, lit, n) == 0;
}

} // namespace

int64_t SliInfo::MaxPosition() const {
	int64_t m = 0;
	for (const SliLabel& l : labels)
		if (l.position > m) m = l.position;
	return m;
}

bool SliInfo::Parse(const std::string& utf8, std::string* error) {
	version.clear();
	labels.clear();
	unit = SliUnit::Unknown;

	// Walk line by line, keeping byte positions so the exact 86-byte layout
	// could be recovered from the parse if it is ever needed.
	size_t lineStart = 0;
	bool sawAny = false;
	while (lineStart <= utf8.size()) {
		size_t nl = utf8.find('\n', lineStart);
		size_t lineEnd = (nl == std::string::npos) ? utf8.size() : nl;
		size_t len = lineEnd - lineStart;
		// Tolerate CRLF; the shipped files are LF but nothing stops another
		// build of WaveLoopManager from writing CRLF.
		if (len && utf8[lineStart + len - 1] == '\r') len--;

		if (len == 0) {
			if (nl == std::string::npos) break;
			lineStart = nl + 1;
			continue;
		}

		if (utf8[lineStart] == '#') {
			// First comment line is the format version: "#2.00".
			if (version.empty() && StartsWith(utf8, lineStart, "#") &&
			    !StartsWith(utf8, lineStart, "# ")) {
				std::string v = utf8.substr(lineStart + 1, len - 1);
				// Trim any stray whitespace.
				while (!v.empty() && (v.back() == ' ' || v.back() == '\t')) v.pop_back();
				version = v;
			}
		} else if (StartsWith(utf8, lineStart, "Label")) {
			size_t posAt = utf8.find("Position=", lineStart);
			if (posAt == std::string::npos || posAt > lineEnd) {
				if (error) *error = "Label without Position= on line " + std::to_string(labels.size() + 1);
				return false;
			}
			size_t numAt = posAt + 9;
			// Accept a leading sign so a malformed value fails loudly below
			// rather than silently parsing as zero.
			const char* begin = utf8.c_str() + numAt;
			char* end = nullptr;
			errno = 0;
			long long value = std::strtoll(begin, &end, 10);
			if (end == begin || errno == ERANGE) {
				if (error) *error = "unparsable Position= value";
				return false;
			}

			SliLabel label;
			label.position = value;

			size_t nameAt = utf8.find("Name=", numAt);
			if (nameAt != std::string::npos && nameAt < lineEnd) {
				size_t q1 = utf8.find('\'', nameAt);
				if (q1 != std::string::npos && q1 < lineEnd) {
					size_t q2 = utf8.find('\'', q1 + 1);
					if (q2 != std::string::npos && q2 < lineEnd)
						label.name = utf8.substr(q1 + 1, q2 - q1 - 1);
				}
			}
			labels.push_back(std::move(label));
			sawAny = true;
		} else {
			// Unknown line: ignored on purpose.  A future .sli revision may add
			// keys, and refusing to load the file would be worse than ignoring
			// what we do not understand.
		}

		if (nl == std::string::npos) break;
		lineStart = nl + 1;
	}

	if (!sawAny) {
		if (error) *error = "no Label entries";
		return false;
	}
	if (version.empty()) {
		if (error) *error = "missing #<version> header";
		return false;
	}
	return true;
}

bool SliInfo::Load(const std::string& path, std::string* error) {
	std::FILE* f = std::fopen(path.c_str(), "rb");
	if (!f) {
		if (error) *error = "cannot open " + path + ": " + std::strerror(errno);
		return false;
	}
	std::string text;
	char buf[4096];
	size_t n;
	while ((n = std::fread(buf, 1, sizeof(buf), f)) > 0) text.append(buf, n);
	std::fclose(f);
	return Parse(text, error);
}

std::string SliInfo::Save() const {
	std::string out;
	out += kHeaderVersion;
	out += '\n';
	out += kHeaderTitle;
	out += '\n';
	out += kHeaderWriter;
	out += '\n';

	for (const SliLabel& label : labels) {
		std::string digits = std::to_string(label.position);
		std::string line = "Label { Position=";
		line += digits;
		line += ';';

		// Pad the "number;" block out to its fixed column.  Real files always
		// have at least one space here, so keep one even for absurd values.
		int pad = kPositionBlock - (int)digits.size() - 1;
		if (pad < 1) pad = 1;
		line.append((size_t)pad, ' ');

		line += "Name='";
		line += label.name;
		line += "';";

		// Pad so the closing brace lands on the same column as the shipped
		// files, i.e. the line is exactly kLabelLineLen bytes.
		int have = (int)line.size() + 1 /*brace*/;
		int trail = kLabelLineLen - have;
		if (trail < 1) trail = 1;
		line.append((size_t)trail, ' ');
		line += '}';
		line += '\n';
		out += line;
	}
	return out;
}

SliUnit ResolveSliUnit(const SliInfo& sli, int64_t durationFrames, int sampleRate) {
	if (durationFrames <= 0 || sampleRate <= 0 || sli.labels.empty()) return SliUnit::Unknown;

	const int64_t maxPos = sli.MaxPosition();
	if (maxPos <= 0) return SliUnit::Unknown;

	// A loop point indexes inside the clip it belongs to, so the unit has to be
	// one where the number still fits.  Milliseconds of the same clip is the
	// competing reading; if Position cannot fit there, it cannot be
	// milliseconds.
	const int64_t durationMs = durationFrames * 1000 / sampleRate;

	const bool fitsSamples = maxPos <= durationFrames;
	const bool fitsMillis = maxPos <= durationMs;

	if (fitsSamples) return SliUnit::Samples;
	if (fitsMillis) return SliUnit::Milliseconds;
	return SliUnit::Unknown; // neither reading makes sense: corrupt pairing
}

int64_t SliPositionToFrames(int64_t position, SliUnit unit, int sampleRate) {
	switch (unit) {
	case SliUnit::Samples:
		return position;
	case SliUnit::Milliseconds:
		return position * (int64_t)sampleRate / 1000;
	case SliUnit::Unknown:
	default:
		return position; // caller decides; treated as samples by default
	}
}

// ---------------------------------------------------------------------------
// LoopPlan
// ---------------------------------------------------------------------------

LoopPlan LoopPlan::Whole(int64_t frames) {
	LoopPlan p;
	p.frames = frames;
	p.introEnd = 0;
	p.loopStart = 0;
	p.loopEnd = frames;
	p.looping = true;
	return p;
}

LoopPlan LoopPlan::FromSli(const SliInfo& sli, int64_t frames, int sampleRate) {
	LoopPlan p;
	p.frames = frames;
	p.looping = true;
	if (sli.labels.empty() || frames <= 0) {
		p.introEnd = 0;
		p.loopStart = 0;
		p.loopEnd = frames > 0 ? frames : 0;
		return p;
	}

	// Several Labels describe several candidate loop points (the tool that
	// wrote them lets an author audition each).  Playback wants the last one:
	// the earlier labels are alternates, and taking the last keeps the longest
	// intro, which is what Artemis' own player does with a multi-label file.
	int64_t pos = sli.labels.back().position;
	int64_t loopAt = SliPositionToFrames(pos, sli.unit, sampleRate);
	if (loopAt < 0) loopAt = 0;
	if (loopAt > frames) loopAt = frames;

	p.introEnd = loopAt;
	p.loopStart = loopAt;
	p.loopEnd = frames;
	// A loop point at the very end would repeat nothing; treat as whole-file.
	if (p.loopEnd - p.loopStart <= 0) {
		p.loopStart = 0;
		p.loopEnd = frames;
	}
	return p;
}

bool LoopPlan::Advance(int64_t* position) const {
	if (!position) return false;
	if (*position < 0) *position = 0;
	if (!looping) return *position < frames;
	if (loopEnd <= loopStart) return false;
	if (*position < loopStart) return true; // still in the intro
	const int64_t len = loopEnd - loopStart;
	if (*position >= loopEnd) *position = loopStart + (*position - loopEnd) % len;
	return true;
}

double RenderStats::Reset() {
	double rms = framesRendered ? std::sqrt(sumSquares / ((double)framesRendered * 2.0)) : 0.0;
	framesRendered = 0;
	peakFrames = 0;
	sumSquares = 0.0;
	peak = 0.0;
	nonSilentFrames = 0;
	return rms;
}

} // namespace audio
} // namespace artemis
